#!/bin/sh
# Bmon OS information: reports the operating system of this host to Bmon-web,
# through the output of a Monit "check program" (one line, read by Bmon-web):
#
#   BMON_OS pretty="Debian GNU/Linux 12 (bookworm)" id="debian" version="12" codename="bookworm" kernel="6.1.0-26-amd64" arch="x86_64"
#
# Always exits 0: it is information, not an alert.
# Generated by Bmon-web AgentConf (template "OS information").

OSR=${BMON_OS_RELEASE:-}
if [ -z "$OSR" ]; then
    for f in /etc/os-release /usr/lib/os-release; do
        [ -r "$f" ] && { OSR=$f; break; }
    done
fi

# value of KEY in os-release, without quotes (the file is parsed, never executed)
val() {
    [ -n "$OSR" ] || return 0
    sed -n "s/^$1=//p" "$OSR" | head -n 1 | sed -e 's/^"\(.*\)"$/\1/' -e "s/^'\(.*\)'\$/\1/"
}
# no double quotes, backslashes or control characters in the output fields
clean() {
    printf '%s' "$1" | tr -d '"\\' | tr '\n\r\t' '   ' | cut -c1-120
}

PRETTY=$(val PRETTY_NAME)
ID=$(val ID)
VERSION=$(val VERSION_ID)
CODENAME=$(val VERSION_CODENAME)
NAME=$(val NAME)

# systems without os-release
if [ -z "$PRETTY$NAME" ]; then
    if command -v lsb_release >/dev/null 2>&1; then
        PRETTY=$(lsb_release -ds 2>/dev/null)
        ID=$(lsb_release -is 2>/dev/null | tr 'A-Z' 'a-z')
        VERSION=$(lsb_release -rs 2>/dev/null)
        CODENAME=$(lsb_release -cs 2>/dev/null)
    elif [ -r /etc/redhat-release ]; then
        PRETTY=$(head -n 1 /etc/redhat-release)
        VERSION=$(printf '%s' "$PRETTY" | sed -n 's/.*release \([0-9][0-9.]*\).*/\1/p')
    elif [ -r /etc/debian_version ]; then
        VERSION=$(head -n 1 /etc/debian_version); ID=debian; PRETTY="Debian $VERSION"
    elif [ -r /etc/alpine-release ]; then
        VERSION=$(head -n 1 /etc/alpine-release); ID=alpine; PRETTY="Alpine Linux $VERSION"
    elif command -v sw_vers >/dev/null 2>&1; then
        VERSION=$(sw_vers -productVersion); ID=macos; PRETTY="macOS $VERSION"
    else
        ID=$(uname -s | tr 'A-Z' 'a-z'); VERSION=$(uname -r); PRETTY="$(uname -s) $VERSION"
    fi
fi
[ -n "$PRETTY" ] || PRETTY=$(printf '%s %s' "$NAME" "$VERSION" | sed 's/ *$//')

printf 'BMON_OS pretty="%s" id="%s" version="%s" codename="%s" kernel="%s" arch="%s"\n' \
    "$(clean "$PRETTY")" "$(clean "$ID")" "$(clean "$VERSION")" "$(clean "$CODENAME")" \
    "$(clean "$(uname -r)")" "$(clean "$(uname -m)")"
exit 0
